31	  }
32	  </script>
33	  <style>
34	    :root {
35	      color-scheme: light dark;
36	      --bg: #ffffff;
37	      --fg: #1a1a1a;
38	      --muted: #555;
39	      --accent: #2563eb;
40	      --border: #e5e7eb;
41	    }
42	
43	    @media (prefers-color-scheme: dark) {
44	      :root {
45	        --bg: #111214;
46	        --fg: #e8e8e8;
47	        --muted: #aaa;
48	        --accent: #60a5fa;
49	        --border: #2a2b2e;
50	      }
51	    }
52	
53	    :root[data-theme="light"] {
54	      color-scheme: light;
55	      --bg: #ffffff;
56	      --fg: #1a1a1a;
57	      --muted: #555;
58	      --accent: #2563eb;
59	      --border: #e5e7eb;
60	    }
61	
62	    :root[data-theme="dark"] {
63	      color-scheme: dark;
64	      --bg: #111214;
65	      --fg: #e8e8e8;
66	      --muted: #aaa;
67	      --accent: #60a5fa;
68	      --border: #2a2b2e;
69	    }
70	
71	    * {
72	      box-sizing: border-box;
73	    }
74	
75	    html {
76	      scroll-behavior: smooth;
77	    }
78	
79	    @media (prefers-reduced-motion: reduce) {
80	      html {
81	        scroll-behavior: auto;
82	      }
83	    }
84	
85	    ::selection {
86	      background: var(--accent);
87	      color: var(--bg);
88	    }
89	
90	    body {
91	      font-family: system-ui, -apple-system, sans-serif;
92	      max-width: 40rem;
93	      margin: 3rem auto;
94	      padding: 0 1rem;
95	      line-height: 1.6;
96	      color: var(--fg);
97	      background: var(--bg);
98	    }
99	
100	    @media (max-width: 30rem) {
101	      body {
102	        margin: 1.5rem auto;
103	      }
104	    }
105	
106	    h1 {
107	      font-size: clamp(1.75rem, 5vw, 2.5rem);
108	      margin-bottom: 0.5rem;
109	    }
110	
111	    p {
112	      color: var(--muted);
113	      max-width: 34rem;
114	    }
115	
116	    a {
117	      color: var(--accent);
118	      transition: opacity 0.15s ease;
119	    }
120	
121	    a:hover {
122	      opacity: 0.8;
123	    }
124	
125	    a:focus-visible,
126	    button:focus-visible {
127	      outline: 2px solid var(--accent);
128	      outline-offset: 2px;
129	    }
130	
131	    .skip-link {
132	      position: absolute;
133	      left: -9999px;
134	      top: 0;
135	      background: var(--accent);
136	      color: var(--bg);
137	      padding: 0.5rem 1rem;
138	      border-radius: 0.25rem;
139	      z-index: 10;
140	    }
141	
142	    .skip-link:focus {
143	      left: 1rem;
144	      top: 1rem;
145	    }
146	
147	    main:focus {
148	      outline: none;
149	    }
150	
151	    nav {
152	      display: flex;
153	      align-items: center;
154	      gap: 1rem;
155	      margin-bottom: 2rem;
156	    }
157	
158	    nav ul {
159	      display: flex;
160	      flex-wrap: wrap;
161	      gap: 1rem;
162	      list-style: none;
163	      padding: 0;
164	      margin: 0;
165	    }
166	
167	    nav a {
168	      text-decoration: none;
169	      font-weight: 500;
170	      opacity: 1;
171	    }
172	
173	    nav a:hover {
174	      text-decoration: underline;
175	    }
176	
177	    nav a[aria-current="page"] {
178	      text-decoration: underline;
179	      color: var(--fg);
180	      font-weight: 700;
181	    }
182	
183	    .theme-toggle {
184	      margin-left: auto;
185	      background: none;
186	      border: 1px solid var(--border);
187	      color: var(--fg);
188	      border-radius: 0.375rem;
189	      padding: 0.25rem 0.6rem;
190	      font: inherit;
191	      font-size: 0.875rem;
192	      cursor: pointer;
193	    }
194	
195	    .theme-toggle:hover {
196	      border-color: var(--accent);
197	    }
198	
199	    h2 {
200	      margin-top: 2rem;
201	      margin-bottom: 0.5rem;
202	    }
203	
204	    section + section {
205	      margin-top: 1.5rem;
206	    }
207	
208	    section {
209	      scroll-margin-top: 1.5rem;
210	    }
211	
212	    footer {
213	      margin-top: 3rem;
214	      padding-top: 1.5rem;
215	      border-top: 1px solid var(--border);
216	      font-size: 0.875rem;
217	      color: var(--muted);
218	    }
219	
220	    @media print {
221	      .skip-link,
222	      nav {
223	        display: none;
224	      }
225	    }
226	  </style>
227	  <script>
228	    (function () {
229	      try {
230	        const stored = localStorage.getItem('theme');
231	        if (stored === 'light' || stored === 'dark') {
232	          document.documentElement.dataset.theme = stored;
233	        }
234	      } catch (e) {
235	        // localStorage may be unavailable (e.g. private browsing); fall back to OS preference.
236	      }
237	    })();
238	  </script>
239	</head>
240	<body>
241	  <a class="skip-link" href="#main">Skip to content</a>
242	  <header>
243	    <nav aria-label="Primary">
244	      <ul>
245	        <li><a href="#home" data-nav-link aria-current="page">Home</a></li>
246	        <li><a href="#about" data-nav-link>About</a></li>
247	        <li><a href="#contact" data-nav-link>Contact</a></li>
248	      </ul>
249	      <button type="button" class="theme-toggle" id="theme-toggle" aria-label="Toggle color theme" aria-pressed="false"><span aria-hidden="true">🌙</span></button>
250	    </nav>
251	  </header>
252	  <main id="main" tabindex="-1">
253	    <section id="home" aria-labelledby="home-heading">
254	      <h1 id="home-heading">My Page</h1>
255	      <p>Welcome. This page is a starting point — replace this text with your own content.</p>
256	    </section>
257	
258	    <section id="about" aria-labelledby="about-heading">
259	      <h2 id="about-heading">About</h2>
260	      <p>Add a short description of what this page or project is about here.</p>
261	    </section>
262	
263	    <section id="contact" aria-labelledby="contact-heading">
264	      <h2 id="contact-heading">Contact</h2>
265	      <p>Reach out at <a href="mailto:hello@example.com">hello@example.com</a>.</p>
266	    </section>
267	  </main>
268	  <footer>
269	    <p>&copy; <span id="year">2026</span> My Page. All rights reserved.</p>
270	  </footer>
271	  <script>
272	    const yearEl = document.getElementById('year');
273	    if (yearEl) yearEl.textContent = String(new Date().getFullYear());
274	
275	    const themeToggle = document.getElementById('theme-toggle');
276	    const prefersDark = window.matchMedia('(prefers-color-scheme: dark)');
277	
278	    const currentTheme = () =>
279	      document.documentElement.dataset.theme || (prefersDark.matches ? 'dark' : 'light');
280	
281	    const updateToggleLabel = () => {
282	      const isDark = currentTheme() === 'dark';
283	      themeToggle.querySelector('span').textContent = isDark ? '☀️' : '🌙';
284	      themeToggle.setAttribute('aria-pressed', String(isDark));
285	      themeToggle.setAttribute('aria-label', isDark ? 'Switch to light theme' : 'Switch to dark theme');
286	    };
287	
288	    updateToggleLabel();
289	
290	    const themeColorMetas = [
291	      document.getElementById('theme-color-light'),
292	      document.getElementById('theme-color-dark'),
293	    ].filter(Boolean);
294	
295	    const syncThemeColorMeta = () => {
296	      const color = getComputedStyle(document.documentElement).getPropertyValue('--bg').trim();
297	      themeColorMetas.forEach(meta => meta.setAttribute('content', color));
298	    };
299	
300	    syncThemeColorMeta();
301	
302	    themeToggle.addEventListener('click', () => {
303	      const next = currentTheme() === 'dark' ? 'light' : 'dark';
304	      document.documentElement.dataset.theme = next;
305	      try {
306	        localStorage.setItem('theme', next);
307	      } catch (e) {
308	        // localStorage may be unavailable; theme still applies for this session.
309	      }
310	      updateToggleLabel();
311	      syncThemeColorMeta();
312	    });
313	
314	    prefersDark.addEventListener('change', () => {
315	      if (!document.documentElement.dataset.theme) updateToggleLabel();
316	    });
317	
318	    const navLinks = document.querySelectorAll('[data-nav-link]');
319	    const sections = [...navLinks]
320	      .map(link => document.querySelector(link.getAttribute('href')))
321	      .filter(Boolean);
322	
323	    const setActive = (id) => {
324	      navLinks.forEach(link => {
325	        if (link.getAttribute('href') === `#${id}`) {
326	          link.setAttribute('aria-current', 'page');
327	        } else {
328	          link.removeAttribute('aria-current');
329	        }
330	      });
331	    };
332	
333	    setActive(sections[0]?.id);
334	
335	    navLinks.forEach(link => {
336	      link.addEventListener('click', () => setActive(link.getAttribute('href').slice(1)));
337	    });
338	
339	    if ('IntersectionObserver' in window) {
340	      const observer = new IntersectionObserver((entries) => {
341	        const visible = entries
342	          .filter(entry => entry.isIntersecting)
343	          .sort((a, b) => b.intersectionRatio - a.intersectionRatio)[0];
344	        if (visible) setActive(visible.target.id);
345	      }, { rootMargin: '-40% 0px -50% 0px' });
346	      sections.forEach(section => section && observer.observe(section));
347	
348	      // The rootMargin above can leave the last section unhighlighted once the
349	      // page is scrolled all the way to the bottom, so force it explicitly.
350	      window.addEventListener('scroll', () => {
351	        const atBottom = window.innerHeight + window.scrollY >= document.documentElement.scrollHeight - 1;
352	        if (atBottom) setActive(sections[sections.length - 1]?.id);
353	      }, { passive: true });
354	    }
355	  </script>
356	</body>
357	</html>
